{
  "severity": "critical",
  "host_observations": [
    {"host": "DC-CORP-02.corp.local", "role": "production-dc", "user": "a.kovacs", "first_seen": "2032-06-25T02:18:08+0000", "last_seen": "2032-06-25T02:23:00+0000"}
