  "attack_progression": [
    {"step": 1, "tactic": "vssadmin list shadows + create shadow on DC volume", "technique": "T1003.003", "what_happened": "At 2032-06-25 02:18:08 UTC on DC-CORP-02 (a domain controller), Sysmon EID 1 captured vssadmin.exe list shadows then vssadmin.exe create shadow /for=C: with parent powershell.exe. The create shadow returned a shadow copy at \\\\?\\GLOBALROOT\\Device\\HarddiskVolumeShadowCopy7. Rule 100116 triggered.", "chain_reason": "vssadmin create shadow on a domain controller is the textbook precursor for NTDS.dit extraction — VSS snapshot lets the attacker bypass the in-use file lock on NTDS.dit while AD is running."},
    {"step": 2, "tactic": "Copy NTDS.dit from shadow path to user temp", "technique": "T1003.003", "what_happened": "At 2032-06-25 02:18:32, Sysmon EID 1 captured cmd.exe /c 'copy \"\\\\?\\GLOBALROOT\\Device\\HarddiskVolumeShadowCopy7\\Windows\\NTDS\\NTDS.dit\" \"C:\\Users\\a.kovacs\\AppData\\Local\\Temp\\p143_ntds_021808\\ntds.dit\"' with parent powershell.exe. Sysmon EID 11 confirmed NTDS.dit (412 MB) created in the destination. Rule 100117 + 100118 triggered.", "chain_reason": "NTDS.dit is the AD database containing every domain account hash. Copying it from a VSS shadow path to user Temp on a DC = full corp-wide hash extraction."},
    {"step": 3, "tactic": "reg save HKLM\\SYSTEM (BootKey for NTDS decrypt)", "technique": "T1003.003", "what_happened": "At 2032-06-25 02:18:48, Sysmon EID 1 captured 'reg.exe save HKLM\\SYSTEM C:\\Users\\a.kovacs\\AppData\\Local\\Temp\\p143_ntds_021808\\system.hive /y'. system.hive (14 MB) created at the same path.", "chain_reason": "NTDS.dit is encrypted with the BootKey stored in HKLM\\SYSTEM. NTDS + SYSTEM hive together → secretsdump.py -ntds ntds.dit -system system.hive LOCAL extracts every domain account hash including krbtgt."},
    {"step": 4, "tactic": "Anti-forensics: vssadmin delete shadows + AMSI tool literals", "technique": "T1003.003", "what_happened": "At 2032-06-25 02:19:20, Sysmon EID 1 captured 'vssadmin.exe delete shadows /all /quiet' — anti-forensic shadow cleanup. AMSI EID 4104 captured scriptblock literals: 'ntdsutil.exe \"ac in ntds\" \"ifm\" \"create full C:\\temp\\ifm\" q q', 'esentutl.exe /y /vss \\\\.\\C:\\Windows\\NTDS\\NTDS.dit /d ntds.copy', 'secretsdump.py -ntds ntds.dit -system system.hive LOCAL'. Multiple T1003.003 toolset literals in one scriptblock.", "chain_reason": "Deleting the VSS shadow after the NTDS copy hides evidence of the snapshot. AMSI tool literals confirm the operator's intent and toolset awareness."}
  ],
  "time_window": {"start": "2032-06-25T02:18:08+0000", "end": "2032-06-25T02:23:00+0000"},
